@@ -0,0 +1,19 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { stockValue } from "../src/domain/reports.js";
+import { fresh } from "./helpers.js";
+
+test("stock value total is the sum of its rounded lines", () => {
+  const store = fresh();
+  const items = store.data.items.slice(0, 2);
+  store.data.batches = [
+    { id: 1, itemId: items[0].id, qty: 1.5, expires: null, receivedAt: "2026-10-01" },
+    { id: 2, itemId: items[1].id, qty: 1.5, expires: null, receivedAt: "2026-10-01" },
+  ];
+  items[0].priceCents = 101;
+  items[1].priceCents = 101;
+  for (const i of store.data.items.slice(2)) i.priceCents = 0;
+  const r = stockValue(store);
+  assert.equal(r.totalCents, r.lines.reduce((s, l) => s + l.valueCents, 0));
+  assert.equal(r.totalCents, 304);
+});
